import React from 'react'
import ServiceCard from './ServiceCard';
import { Col } from 'reactstrap';

import weatherImg from "../assets/images/weather.png";
import guideImg from "../assets/images/guide.png";
import customizationImg from "../assets/images/customization.png";


const serviceData = [
    {
        imgUrl: weatherImg,
        title: "Calculate Weather",
        desc: "In Visual Studio Code, you can create custom code snippets or use extensions for code snippet suggestions tailored to your needs. Here’s how to set them up:"
    },
    {
        imgUrl: guideImg,
        title: "Best Tour Guide",
        desc: "In Visual Studio Code, you can create custom code snippets or use extensions for code snippet suggestions tailored to your needs. Here’s how to set them up:"
    },
    {
        imgUrl: customizationImg,
        title: "Customization",
        desc: "In Visual Studio Code, you can create custom code snippets or use extensions for code snippet suggestions tailored to your needs. Here’s how to set them up:"
    }

]
const ServiceList = () => {
    return (
        <>
            {serviceData.map((item, index) => (<Col lg='3' key={index}><ServiceCard item={item} /> </Col>))}
        </>
    )
}

export default ServiceList
